      ]
    },
    {
      "subject": "Malaysian answer",
      "conclusion": "\"pemegang akaun\" is an ordinary, accurate Malaysian banking term, but \"pemilik akaun\" is also used in Malaysian bank materials for the account owner or holder.",
      "material_risk": true,
      "evidence_refs": [
        "https://www.maybank2u.com.my/iwov-resources/pdf/personal/tnc/governBankAcc-Isl-bm.pdf",
